INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Datenflussplan dasselbe wie ein Datenflussdiagramm?', 2, '[{"text": "Ja", "correct": true, "because": "Synonyme Begriffe"}, {"text": "Nein", "correct": false, "because": "Beide visualisieren Datenflüsse"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Datenflussplan?', 3, '[{"text": "Datenflüsse visualisieren", "correct": true, "because": "Zeigt Verarbeitungsschritte"}, {"text": "Hardware konfigurieren", "correct": false, "because": "Kein Hardware-Fokus"}, {"text": "Netzwerk sichern", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einem Datenflussplan?', 5, '[{"text": "Prozesse", "correct": true, "because": "Verarbeitungsschritte"}, {"text": "Datenflüsse", "correct": true, "because": "Datenbewegung"}, {"text": "Grafiktreiber", "correct": false, "because": "Kein Diagrammteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Datenflussplan zeigt Prozesse. b) Er definiert Hardware.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nicht Ziel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Datenflussplan?', 4, '[{"text": "Datenquellen", "correct": false, "because": "Wichtig für Fluss"}, {"text": "Prozessschritte", "correct": false, "because": "Kern des Plans"}, {"text": "Bildschirmfarbe", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Datenflussplan immer physisch ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch logische Flüsse möglich"}, {"text": "Ja", "correct": false, "because": "Abstraktionsebene variiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Symbol zeigt einen Prozess im Datenflussplan?', 3, '[{"text": "Kreis", "correct": true, "because": "Standard für Prozesse"}, {"text": "Pfeil", "correct": false, "because": "Zeigt Fluss"}, {"text": "Quadrat", "correct": false, "because": "Datenquelle/-speicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Datenflussplan?', 5, '[{"text": "Klarheit", "correct": true, "because": "Visualisiert Abläufe"}, {"text": "Analyse", "correct": true, "because": "Erkennt Engpässe"}, {"text": "Hardware-Optimierung", "correct": false, "because": "Kein Hardware-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Datenflusspläne sind für Entwickler. b) Sie sind immer statisch. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Können angepasst werden"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen Datenflussplan?', 4, '[{"text": "Prozesse", "correct": false, "because": "Kern des Diagramms"}, {"text": "Datenflüsse", "correct": false, "because": "Zeigen Bewegung"}, {"text": "3D-Drucker", "correct": true, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Zeigt ein Datenflussplan die Hardware?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf Datenfluss"}, {"text": "Ja", "correct": false, "because": "Logische Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ebenen kann ein Datenflussplan darstellen?', 4, '[{"text": "Logisch", "correct": true, "because": "Abläufe unabhängig"}, {"text": "Physisch", "correct": true, "because": "Mit Systemdetails"}, {"text": "Grafisch", "correct": false, "because": "Kein Ebenentyp"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Datenflussplan nur für große Systeme ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für kleine Projekte"}, {"text": "Ja", "correct": false, "because": "Universell einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Datenflussplan?', 3, '[{"text": "Übersichtlichkeit", "correct": true, "because": "Verständnis entscheidend"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Genauigkeit wichtiger"}, {"text": "Minimale Größe", "correct": false, "because": "Klarheit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Datenflusspläne zeigen Datenbewegung. b) Sie sind nur für Programmierer.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Analysten nutzen sie"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bestandteile sind essenziell?', 5, '[{"text": "Datenquellen", "correct": true, "because": "Startpunkt"}, {"text": "Datenspeicher", "correct": true, "because": "Speicherorte"}, {"text": "Farbcodierung", "correct": false, "because": "Optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist im Datenflussplan unwichtig?', 3, '[{"text": "Datenflussrichtung", "correct": false, "because": "Kern des Plans"}, {"text": "Prozessbeschreibung", "correct": false, "because": "Erklärt Schritte"}, {"text": "Monitorhelligkeit", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Zeigt ein Datenflussplan Zeitabläufe?', 3, '[{"text": "Nein", "correct": true, "because": "Fokus auf Fluss, nicht Zeit"}, {"text": "Ja", "correct": false, "because": "Zeit ist Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Datenflusspläne nur für Software sind?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Geschäftsprozesse"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielen Datenflüsse?', 4, '[{"text": "Verbindungen zeigen", "correct": true, "because": "Datenweg darstellen"}, {"text": "Hardware definieren", "correct": false, "because": "Kein Fokus"}, {"text": "Sicherheit erhöhen", "correct": false, "because": "Indirekt"}]');
